static int rx_search_run(const unsigned char *subject, size_t subject_length,
       size_t search_from, ptrdiff_t (*capture_spans)[2], rx_run_state *run)
{
    rx_ctx ctx;
    ptrdiff_t result;
    size_t attempt_position;
    size_t window_end;
    if (search_from > subject_length) return 0;
    size_t handoff_position = ({ const void *rx_mf2_q = subject_length > search_from ? memchr(subject + search_from, 97, subject_length - search_from) : NULL; rx_mf2_q ? (size_t)((const unsigned char *)rx_mf2_q - (const unsigned char *)subject) : subject_length; });
    if (handoff_position >= subject_length) return 0;
    if (handoff_position - search_from > 2) {
        handoff_position -= 2;
    } else
        handoff_position = search_from;
    {
        ptrdiff_t window[1][2];
        if (rx_prefilter(subject, subject_length, handoff_position, window) != 1) return 0;
        attempt_position = (size_t)window[0][0];
        window_end = subject_length;  /* cut-bearing artifact: the prefilter answers for the UNCUT language, so its span END is not a bound on this match's end */
    }
    rx_run_state_init(run);
    ctx.subject = subject; ctx.len = subject_length; ctx.ncap = 0;
    ctx.caps = NULL; ctx.user = NULL;
    for (;;) {
        ctx.pos = attempt_position;
        result = rx_match_anchored(&ctx, run, window_end);
        if (result == RX_R_STEPS)   return PCREC_ERR_STEPS;
        if (result == RX_R_FRAMES)  return PCREC_ERR_FRAMES;
        if (result == RX_R_WORK)    return PCREC_ERR_WORK;
        if (result == RX_R_RECURSE) return PCREC_ERR_RECURSE;
        if (result == RX_R_INTERNAL) return PCREC_ERR_INTERNAL;
        if (result >= 0) break;
        rx_reset_for_next_attempt(run);
        if (attempt_position >= subject_length) return 0;
        attempt_position++;
        {
            ptrdiff_t window[1][2];
            if (rx_prefilter(subject, subject_length, attempt_position, window) != 1) return 0;
            attempt_position = (size_t)window[0][0];
            window_end = subject_length;
        }
    }
    if (capture_spans) rx_report_captures(run, capture_spans, attempt_position, result);
    return 1;
}

int rx_search(const unsigned char *subject, size_t subject_length, size_t search_from,
       ptrdiff_t (*capture_spans)[2])
{
    rx_run_state run;
    rx_run_buffers storage;   /* this artifact's stamped default */
    rx_run_state_bind(&run, storage.frames, RX_RESUME_FRAMES,
                            storage.trail,  RX_TRAIL_FRAMES);
    return rx_search_run(subject, subject_length, search_from, capture_spans, &run);
}

int rx_search_in(const unsigned char *subject, size_t subject_length, size_t search_from,
          ptrdiff_t (*capture_spans)[2], const rx_buffers *buffers)
{
    rx_run_state run;
    if (!buffers) return rx_search(subject, subject_length, search_from, capture_spans);
    rx_run_state_bind(&run, buffers->frames, buffers->nframes,
                            buffers->trail,  buffers->ntrail);
    return rx_search_run(subject, subject_length, search_from, capture_spans, &run);
}

